export class TabIndicator {
  private pending: number = 0
  setPending(tab: number): void { this.pending = tab }
}

sources.Telemetry.ets:
export class Telemetry {
  reportPacket(): void {
    console.error('packet buffered after reconnect')
  }
  reportDynamic(key: string): void {
    console.error(`packet ${key} buffered after reconnect`)
  }
}

