import { Telemetry } from './Telemetry'
export class RetryPanel {
  private telemetry: Telemetry = new Telemetry()
  retry(): void { this.telemetry.reportPacket() }
  dynamicRetry(key: string): void { this.telemetry.reportDynamic(key) }
}
